  ACT['mk-cr-f'] = el => { const F = UI.mkCr || (UI.mkCr = { buyer: '', amount: 30000000, bundle: false, bonusBp: null }); const k = el.dataset.k; if (k === 'buyer') F.buyer = el.value.trim(); if (k === 'amount') { F.amount = Math.max(0, Math.round(+el.value || 0)); F.bonusBp = null; } if (k === 'bundle') { F.bundle = el.value === '1'; F.bonusBp = null; } if (k === 'bonus') F.bonusBp = Math.max(0, Math.round((+el.value || 0) * 100)); render(); };
